# DFS assembling pieces by marker-to-marker coincidence, 4 anchored; no color-color overlaps.
objs={'6':(six,m6),'1':(one,m1),'3':(three,m3),'5':(five,m5)}
baseC=four;baseM=m4
# Generate valid placement candidates for each piece anywhere in grid without overlap with base color.
placements={}
for nm,(cells,marks) in objs.items():
 opts=[]
 for dr in range(-25,26):
  for dc in range(-25,26):
   cc=move(cells,(dr,dc)); mm=move(marks,(dr,dc))
   if not cc or min(r for r,c in cc)<0 or max(r for r,c in cc)>=22 or min(c for r,c in cc)<0 or max(c for r,c in cc)>=22: continue
   if cc&baseC or mm&baseC or cc&baseM: continue # require no color-marker contact with 4
   opts.append((dr,dc,cc,mm))
 placements[nm]=opts
 print(nm,len(opts))

# Generate candidates requiring only no color-color overlap with anchor; markers may sit on colors.
placements_loose={}
for nm,(cells,marks) in objs.items():
 opts=[]
 for dr in range(-25,26):
  for dc in range(-25,26):
   cc=move(cells,(dr,dc)); mm=move(marks,(dr,dc))
   if not cc or min(r for r,c in cc)<0 or max(r for r,c in cc)>=22 or min(c for r,c in cc)<0 or max(c for r,c in cc)>=22: continue
   if cc&baseC: continue
   opts.append((dr,dc,cc,mm))
 placements_loose[nm]=opts
# DFS for all connected marker overlap, only color-color collisions
bestlo=[]; nodeslo=0
def searchlo(state, rem, score):
 global nodeslo
 nodeslo+=1
 if not rem:
  bestlo.append((score,state.copy())); return
 curM=set(baseM); curC=set(baseC)
 for nm,(dr,dc,cc,mm) in state.items(): curM|=mm; curC|=cc
